"""Follow-up questions about Lumi's OWN previous answer, written blind (2026-10-22) from knowledge/*.md, docs/14 and
docs/17 only. A setup turn fixes what Lumi said (its "reply" goes into the history as said, not generated, not scored);
the next turns ask about that answer ("why?", "how do you know?", "really?", "where?", "왜?", "진짜요?", "어떻게?",
"언제?", "어디?", "뭐?"), nested up to four levels, several chains in one visit (long ones 8-20 turns). EN, KO (반말,
해요체, 하십시오체), mixed, whisper slips ("wai?", "와이?").

DIALOGUES = [{"who", "topic", "lang": "en" | "ko" | "mix", "turns": [turn, ...]}]
turn = {"say", "reply" (only on setup turns: Lumi's line as said), "scored": bool, "expect_action": "none" | action,
        "must": [regex], "must_not": [regex], "check": one line for the judge}
- scored False with a "reply": put the reply into the history, do not ask the model. scored False without a reply
  (a back-channel between chains): let Lumi answer, do not judge it.
- scored True: the reply must go on from Lumi's previous answer: answer what was asked (its reason, the fact again
  after "really?"), no hesitation ("what do you mean?"), no topic change, no help offer, nothing made up.
  must / must_not: case-insensitive regexes on the spoken reply (every must matches, no must_not does).
Checked like tests/dialogues.py (tests/dialogue_check.py), with the fixed replies put into the history.

held-out: only scored, never read by whoever fixes the code.
"""

